'use strict';
Object.assign(V,{
 'GAR-02':()=>{const list=M.clothes.filter(c=>(!M.clothingFilter||M.clothingFilter==='Toutes'||c.category===M.clothingFilter)&&fold(c.name+' '+c.color).includes(fold(M.clothingQuery)));return head('Mon dressing','Retrouver vos pièces et inventer de nouvelles associations.')+A('Ajouter une pièce','new-clothing')+form('clothing-filter',field('q','Rechercher une pièce ou une couleur',M.clothingQuery||''),'Rechercher')+chips(['Toutes','Haut','Bas','Robe','Chaussures','Accessoire'],'clothingFilter',M.clothingFilter||'Toutes')+(list.length?`<div class="grid2 content-grid">${list.map(c=>`<article class="content-card">${A(`${imageFor(c.image||'work')}<span class="card-type">${esc(c.category)}, ${esc(c.color)}</span><h3>${esc(c.name)}</h3>`,'edit-clothing',{id:c.id},'')}${A(icon('x'),'delete-clothing-request',{id:c.id,label:'Retirer '+c.name},'heart-save')}</article>`).join('')}</div>`:empty(M.clothes.length?'Aucune pièce correspondante':'Commencez avec une pièce que vous aimez',M.clothes.length?'Changez de catégorie ou de recherche.':'Pas besoin de photographier tout votre placard. Ajoutez vos essentiels au fil de vos envies.')+(M.clothes.length?A('Voir toutes mes pièces','clothing-reset',{},'secondary'):''))+A('Composer une tenue','new-outfit',{},'secondary mt')+sec('Mes tenues')+grid(M.outfits.filter(x=>x.pieces))},
 'GAR-03':()=>{const c=M.clothingEdit||{name:'',category:'Haut',color:'',season:'Toutes',image:'work'};return head(c.id?'Modifier ma pièce':'Une nouvelle pièce')+imageFor(M.context.clothingPhoto||c.image,'detail-photo')+A('Choisir une photo','file-pick',{purpose:'clothing'},'secondary mb')+form('clothing',field('name','Nom de la pièce',c.name,'text',true)+select('category','Catégorie',['Haut','Bas','Robe','Chaussures','Accessoire'],c.category)+field('color','Couleur',c.color)+select('season','Saison',['Toutes','Printemps','Été','Automne','Hiver'],c.season)+area('notes','Notes — facultatif',c.notes||''),'Garder cette pièce')+note('Une illustration d’exemple est proposée si vous n’importez pas de photo.');},
 'GAR-04':()=>{const o=M.outfitEdit||{};return head(o.id?'Ajuster ma tenue':'Composer ma tenue','Associez ce que vous avez déjà.')+(M.clothes.length?form('outfit',field('name','Nom de ma tenue',o.name||'','text',true)+select('occasion','Pour quelle occasion ?',['Quotidien','Travail','Rendez-vous','Événement'],o.occasion||'Quotidien')+M.clothes.map(c=>`<label class="glass check-task"><input type="checkbox" name="piece${c.id}" ${(o.pieces||[]).includes(c.id)?'checked':''}>${imageFor(c.image||'work','avatar')}<span class="label"><strong>${esc(c.name)}</strong><small>${esc(c.category)}, ${esc(c.color)}</small></span></label>`).join('')+area('notes','Une note — facultatif',o.desc||''),'Garder ma tenue'):empty('Ajoutez vos premières pièces','Quelques vêtements suffisent pour commencer.','GAR-02','Mon dressing'))},
 'ESS-01':()=>{const x=currentLook();return head('Explorer cette référence','Un aperçu illustratif')+(!x?empty('Choisissez une inspiration','Vous pourrez ensuite explorer le rendu.','DEC-01','Découvrir'): `<div class="comparison"><div>${imageFor(M.simulationPhoto||'bun')}<h3>Ma référence</h3><small>${M.simulationPhoto?'Photo sélectionnée':'Photo d’exemple'}</small></div><div>${imageFor(x.image)}<h3>Mon inspiration</h3><small>${esc(x.name)}</small></div></div>`+A('Changer la photo','file-pick',{purpose:'simulation'},'secondary mt')+panel(P('Ce prototype affiche une référence prédéfinie. Il ne transforme pas votre photo.'))+form('simulation-consent',check('consent','J’ai compris le caractère illustratif de cet aperçu.'),'Préparer l’aperçu'))+B('Revenir à l’inspiration','DEC-03','text-button mt')},
 'ESS-02':()=>head('Votre aperçu se prépare','Votre sélection est conservée.')+panel(`${icon('spark','glow-icon xl')}${P(M.scenario==='error'?'L’aperçu n’est pas disponible. Vous pouvez réessayer.':M.scenario==='pending'?'L’aperçu est en attente.':'La référence illustrée est prête.')}`)+A('Afficher mon aperçu','finish-simulation')+B('Revoir ma sélection','ESS-01','secondary mt')+note('Aucune transformation de photo n’est calculée.'),
 'ESS-03':()=>{const x=M.simulations.find(x=>x.id===M.context.simulation);return head('Mon aperçu','Référence illustrative')+(x?`<div class="comparison"><div>${x.source?imageFor(x.source):panel(P('Photo retirée'))}<h3>Ma référence</h3></div><div>${imageFor(x.image)}<h3>Mon inspiration</h3></div></div>`+note('Cette image est une référence prédéfinie. Ce n’est pas une transformation de votre visage.')+A(M.saved.includes(x.id)?'Aperçu enregistré':'Garder cet aperçu','save',{id:x.id})+A('Réaliser ce look','tutorial',{id:x.look},'secondary mt')+B('Choisir une autre inspiration','DEC-02','text-button mt'):empty('Cet aperçu n’est plus disponible','Choisissez une inspiration pour commencer.','DEC-01','Découvrir'))},
 'ACH-01':()=>{const x=item(M.context.product)||item('foundation');return head('Où trouver ce produit ?',esc(x.name))+imageFor(x.image,'detail-photo')+tag('Scénario de vendeur externe')+P('Dans cette option, la vente et le paiement se dérouleraient chez le vendeur. Beautify ne crée ni panier ni commande externe.')+panel(`<h3>Boutique d’exemple A</h3>${P('Offre fictive, '+money(x.price)+', disponibilité simulée')}${A('Ouvrir le vendeur — simulation','external-vendor',{name:'Boutique d’exemple A'},'secondary')}`)+panel(`<h3>Boutique d’exemple B</h3>${P('Prix non communiqué, disponibilité inconnue')}${A('Ouvrir le vendeur — simulation','external-vendor',{name:'Boutique d’exemple B'},'secondary')}`)+note('Aucun lien marchand réel n’est utilisé et aucun résultat de proximité n’est inventé.')+B('Retour à la fiche produit','DEC-06','secondary mt');},
 'ACH-02':()=>head('Mon panier','Produits de démonstration')+(M.cart.length?M.cart.map((c,i)=>cartLine(c,i)).join('')+receipt()+B('Continuer ma commande — démo','ACH-03'):empty('Une envie à retrouver ?','Les produits sélectionnés auront leur place ici.')+A('Explorer les produits','catalog',{type:'Produit'},'secondary'))+(M.orders.some(o=>o.status==='pending')?row('Une commande attend sa confirmation','Les articles concernés sont déjà dans cette commande.','ACH-07','bag'):'')+A('Continuer à découvrir','catalog',{type:'Produit'},'text-button mt')+MOCK_NOTICE,
 'ACH-03':()=>head('Coordonnées & livraison','Utilisez les données d’exemple pour ce parcours fictif.')+A('Remplir avec l’exemple','fill-shipping',{},'secondary mb')+form('shipping',field('name','Nom de démonstration',M.checkout.name||'','text',true)+field('email','Email de démonstration',M.checkout.email||'','email',true)+field('address','Adresse fictive',M.checkout.address||'','text',true)+field('city','Ville fictive',M.checkout.city||'','text',true)+field('postal','Code postal fictif',M.checkout.postal||'','text',true)+select('method','Livraison de démonstration',['Standard : 4,90 €','Express : 8,90 €'],M.checkout.method==='express'?'Express : 8,90 €':'Standard : 4,90 €'),'Vérifier la commande')+MOCK_NOTICE,
 'ACH-04':()=>head('Vérifier ma commande','Dernière vérification avant le paiement simulé.')+(M.cart.length?panel(`<h3>Livraison</h3>${P(esc(M.checkout.name||'Nom à renseigner'))}${P(esc(M.checkout.address||'Adresse à renseigner')+'<br>'+esc(M.checkout.postal||'')+' '+esc(M.checkout.city||''))}${B('Modifier la livraison','ACH-03','text-button')}`)+M.cart.map((c,i)=>cartLine(c,i,false)).join('')+receipt()+B('Payer — démonstration','ACH-05')+B('Modifier les articles','ACH-02','secondary mt')+B('Informations sur le mockup','PRF-11','text-button mt'):empty('Aucun article à commander','Le panier doit contenir un produit de démonstration.','ACH-02','Mon panier'))+MOCK_NOTICE,
 'ACH-05':()=>head('Confirmer ma commande','Paiement de démonstration')+(M.cart.length?receipt()+MOCK_NOTICE+A('Confirmer le paiement — démo','pay')+B('Revoir ma commande','ACH-04','secondary mt'):empty('Aucun article à confirmer','Retrouvez votre panier ou vos commandes.','ACH-02','Mon panier')),
 'ACH-06':()=>{const o=M.orders.find(x=>x.id===M.context.order);return head(o?.status==='confirmed'?'Commande démo confirmée':o?.status==='pending'?'Paiement en attente':'Commande non confirmée')+icon(o?.status==='confirmed'?'check':o?.status==='pending'?'more':'x','success-icon')+(o?panel(`<h3>${esc(o.reference)}</h3>${P(orderStatus(o))}${P(money(o.total)+', '+dateText(o.date))}${note('Commande fictive. Aucun article ne sera expédié.')}`):P('Aucune commande de démonstration n’a été créée.'))+(o?.status==='pending'?A('Vérifier le paiement — simulation','verify-order'):'')+(o?.status==='failed'?B('Revenir à la vérification','ACH-04','secondary mt'):'')+B('Voir mes commandes','ACH-07')+B('Retour à l’accueil','ACC-01','secondary mt');},
 'ACH-07':()=>head('Mes commandes','Retrouver chaque commande et son statut.')+(M.orders.length?M.orders.slice().reverse().map(o=>panel(`<div class="between"><h3>${esc(o.reference)}</h3>${tag(orderStatus(o))}</div>${P(dateText(o.date)+', '+money(o.total))}${A('Voir le détail','order-detail',{id:o.id},'secondary')}`)).join(''):empty('Aucune commande pour le moment','Les commandes de démonstration seront regroupées ici.')+A('Explorer les produits','catalog',{type:'Produit'},'secondary')),
});
function cartLine(c,i,edit=true){const x=item(c.id);if(!x)return panel(P('Cet article est indisponible.')+A('Retirer','cart-remove',{index:i},'text-button'));return `<section class="glass cart-line">${photo(x.image)}<div><h3>${esc(x.name)}</h3><p>${esc(c.variant)}, ${money(x.price)}</p>${edit?`<div class="qty-control">${A('−','quantity',{index:i,delta:-1,label:'Diminuer la quantité de '+x.name},'')}<span>${c.qty}</span>${A('+','quantity',{index:i,delta:1,label:'Augmenter la quantité de '+x.name},'')}${A('Retirer','cart-remove',{index:i},'text-button')}</div>`:P('Quantité : '+c.qty)}</div><strong class="accent">${money(c.qty*x.price)}</strong></section>`;}
function receipt(){const t=totals();return panel(`<div><span>Sous-total</span><span>${money(t.subtotal)}</span></div><div><span>Livraison fictive</span><span>${money(t.shipping)}</span></div><div class="total"><strong>Total démo</strong><strong>${money(t.total)}</strong></div>`,'receipt');}
function orderStatus(o){return ({confirmed:'Confirmée — démo',pending:'En attente',failed:'Paiement refusé',cancelled:'Annulée — démo',return:'Retour demandé — démo',shipped:'Expédiée — démo'})[o.status]||'Statut inconnu';}
function orderDetail(){const o=M.orders.find(x=>x.id===M.context.orderDetail);if(!o)return '';return sec('Détail de la commande')+panel(`<h3>${esc(o.reference)}</h3>${P(orderStatus(o))}${o.lines.map(c=>P(esc(item(c.id)?.name||'Article indisponible')+', '+c.qty+' × '+money(c.price))).join('')}${P('Total de la commande : '+money(o.total))}${P('Livraison fictive : '+esc(o.address||'Adresse d’exemple'))}${o.status==='pending'?A('Vérifier le statut','verify-order',{id:o.id},'secondary'):''}${o.status==='confirmed'?A('Simuler une expédition','order-status',{id:o.id,status:'shipped'},'secondary'):''}${o.status==='confirmed'||o.status==='pending'?A('Demander une annulation','order-cancel-request',{id:o.id},'secondary mt'):''}${o.status==='shipped'?A('Demander un retour','order-return',{id:o.id},'secondary mt'):''}${A('Contacter le support — démo','order-support',{id:o.id},'text-button mt')}`);}
Object.assign(F,{
 clothing:d=>{const c={...(M.clothingEdit||{}),id:M.clothingEdit?.id||uid('clothing'),name:d.name,category:d.category,color:d.color,season:d.season,notes:d.notes,image:M.context.clothingPhoto||M.clothingEdit?.image||'work'};const i=M.clothes.findIndex(x=>x.id===c.id);if(i>=0)M.clothes[i]=c;else M.clothes.push(c);M.context.clothingPhoto='';M.clothingEdit=null;go('GAR-02');toast('Pièce ajoutée au dressing du mockup.');},
 'outfit':d=>{const pieces=Object.keys(d).filter(k=>k.startsWith('piece')&&d[k]).map(k=>k.slice(5)).filter(id=>M.clothes.some(c=>c.id===id));if(!pieces.length)return formError('Choisissez au moins une pièce.');const old=M.outfitEdit||{},first=M.clothes.find(x=>x.id===pieces[0]),x={...old,id:old.id||uid('outfit'),name:d.name,occasion:d.occasion,desc:d.notes||'Composée avec mes pièces.',pieces,image:first?.image||'wardrobe',type:'Look',domain:'Personnel'},i=M.outfits.findIndex(o=>o.id===x.id);if(i>=0)M.outfits[i]=x;else M.outfits.push(x);M.outfitEdit=null;if(!M.saved.includes(x.id))M.saved.push(x.id);go('DEC-03',{context:{look:x.id}});toast('Tenue gardée dans votre dressing et vos enregistrés.')},
 'simulation-consent':d=>{if(!d.consent)return formError('Confirmez le caractère illustratif de cet aperçu.');if(!currentLook())return formError('Choisissez une inspiration disponible.');M.simulationDraft={id:uid('simulation'),source:M.simulationPhoto||'bun',look:M.context.look};go('ESS-02');},
 shipping:d=>{M.checkout={...M.checkout,...d,method:d.method.startsWith('Express')?'express':'standard',shipping:d.method.startsWith('Express')?8.9:4.9};go('ACH-04');},
 'return-request':d=>{const o=M.orders.find(x=>x.id===M.context.order);if(o){o.returnReason=d.reason;o.status='return';M.context.orderDetail=o.id;}closeModal();render();toast('Demande de retour enregistrée dans le mockup.');}
});
Object.assign(ACTIONS,{
 'new-clothing':()=>{M.clothingEdit=null;M.context.clothingPhoto='';clearDrafts('clothing');go('GAR-03');},
 'edit-clothing':d=>{M.clothingEdit={...M.clothes.find(x=>x.id===d.id)};M.context.clothingPhoto='';clearDrafts('clothing');go('GAR-03');},
 'delete-clothing-request':d=>confirmAction('Retirer cette pièce du dressing ?','Les tenues existantes seront conservées mais cette pièce y sera signalée comme indisponible.','delete-clothing',d),
 'delete-clothing':d=>{M.clothes=M.clothes.filter(x=>x.id!==d.id);closeModal();render();},
 'finish-simulation':()=>{if(['error','offline'].includes(M.scenario)){M.scenario='normal';render();toast('Votre sélection est conservée. Réessayez.');return;}const draft=M.simulationDraft,look=item(draft?.look);if(!draft||!look){go('ESS-01');return;}let x=M.simulations.find(x=>x.id===draft.id);if(!x){x={id:draft.id,name:'Aperçu : '+look.name,source:draft.source,look:look.id,image:look.image,type:'Simulation',domain:look.domain,date:DATE(),desc:'Référence illustrative — aucune transformation calculée.'};M.simulations.push(x);}M.scenario='normal';go('ESS-03',{context:{simulation:x.id,look:x.look}});},
 'external-vendor':d=>modal(esc(d.name),P('Ce bouton simule une redirection vers un vendeur externe. Dans le produit réel, ce vendeur traiterait le paiement, la commande et le service après-vente.')+P('Aucun site externe n’est ouvert dans ce mockup.')+A('Revenir à Beautify','close')),
 quantity:d=>{const c=M.cart[Number(d.index)];if(c)c.qty=Math.max(1,Math.min(99,c.qty+Number(d.delta)));M.checkout.pendingOrder=null;render();},
 'cart-remove':d=>{M.cart.splice(Number(d.index),1);M.checkout.pendingOrder=null;render();},
 'fill-shipping':()=>{M.checkout={...M.checkout,name:'Mia Démo',email:'mia@example.test',address:'12 avenue Exemple — adresse fictive',city:'Ville Démo',postal:'00000'};delete M.formDrafts.shipping;render();},
 'pay':d=>{if(!M.cart.length){go('ACH-02');return;}const status=d.status||(['error','refused'].includes(M.scenario)?'failed':M.scenario==='pending'?'pending':'confirmed'),t=totals(),o={id:uid('order'),reference:'DEMO-'+String(M.orders.length+1).padStart(4,'0'),date:DATE(),status,lines:M.cart.map(c=>({...c,price:item(c.id)?.price||0})),total:t.total,shipping:t.shipping,address:M.checkout.address||'Adresse fictive',cartTransferred:status!=='failed'};M.orders.push(o);if(o.cartTransferred)M.cart=[];M.checkout.pendingOrder=null;M.scenario='normal';go('ACH-06',{context:{order:o.id,orderDetail:o.id}});},
 'verify-order':d=>{const id=d.id||M.context.order,o=M.orders.find(x=>x.id===id);if(!o)return;if(o.status==='pending')o.status='confirmed';if(M.checkout.pendingOrder===o.id)M.checkout.pendingOrder=null;M.context.order=id;M.scenario='normal';closeModal();go('ACH-06',{context:{order:id}});toast('Commande démo confirmée. Aucun débit réel.');},
 'order-detail':d=>{M.context.orderDetail=d.id;M.context.order=d.id;modal('Ma commande',orderDetail());},
 'order-status':d=>{const o=M.orders.find(x=>x.id===d.id);if(o)o.status=d.status;closeModal();render();},
 'order-cancel-request':d=>confirmAction('Annuler cette commande fictive ?','Le statut sera modifié dans le mockup. Aucun remboursement réel n’est impliqué.','order-status',{id:d.id,status:'cancelled'}),
 'order-return':d=>{M.context.order=d.id;modal('Demander un retour — démo',form('return-request',select('reason','Motif de démonstration',['Ne convient pas','Article fictif endommagé','Autre'],'Ne convient pas')+P('Cette demande reste dans le mockup. Aucune étiquette de retour ni prise en charge réelle ne sera créée.'),'Garder ma demande de retour'));},
 'order-support':d=>{M.context.order=d.id;M.formDrafts.support={topic:'Commande',message:'À propos de '+M.orders.find(x=>x.id===d.id)?.reference};go('PRF-10');}
});

Object.assign(ACTIONS,{
 'new-outfit':()=>{M.outfitEdit=null;clearDrafts('outfit');go('GAR-04');},
 'edit-outfit':d=>{const o=M.outfits.find(o=>o.id===(d.id||M.context.look));if(!o)return;M.outfitEdit=clone(o);clearDrafts('outfit');go('GAR-04');},
 'clothing-reset':()=>{M.clothingQuery='';M.clothingFilter='Toutes';clearDrafts('clothing-filter');render();}
});
F['clothing-filter']=d=>{M.clothingQuery=d.q;render();};
